1	// The pages shoppers see. Server-rendered with Hono JSX, plus a few lines of browser script.
2	
3	import { raw } from "hono/html";
4	import type { Child } from "hono/jsx";
5	import { bugIsOn } from "./bugs";
6	import type { PricedLine, Product, Totals } from "./domain/basket";
7	import type { Slot } from "./domain/slots";
8	import type { Order, Shopper } from "./store";
9	
10	export const release = () => (process.env.RELEASE ?? "v1").trim();
11	const isReleaseTwo = () => release() === "v2";
12	
13	export const money = (cents: number) => {
14	  const sign = cents < 0 ? "-" : "";
15	  const dollars = (Math.abs(cents) / 100).toFixed(2);
16	  return `${sign}$${dollars}`;
17	};
18	
19	export const grams = (weight: number) => {
20	  const isWholeKilograms = weight >= 1000 && weight % 1000 === 0;
21	  return isWholeKilograms ? `${weight / 1000} kg` : `${weight} g`;
22	};
23	
24	export const LABELS = {
25	  add: () => (isReleaseTwo() ? "Add to basket" : "Add"),
26	  book: () => (isReleaseTwo() ? "Reserve" : "Book slot"),
27	  checkout: () => "Checkout",
28	};
29	
30	const CSS = `
31	:root {
32	  --green:#1f6f4a; --ink:#1d2421; --muted:#5b6660; --line:#dfe5e1; --bg:#f6f8f6; --warn:#a4400b;
33	}
34	* { box-sizing: border-box; }
35	body {
36	  margin:0; font: 16px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
37	  color:var(--ink); background:var(--bg);
38	}
39	header {
40	  background:var(--green); color:#fff; padding:12px 20px; display:flex; gap:20px;
41	  align-items:center; flex-wrap:wrap;
42	}
43	header .brand {
44	  font-weight:700; font-size:20px; margin-right:auto; color:#fff; text-decoration:none;
45	}
46	header a { color:#fff; }
47	header .who { font-size:14px; opacity:.9; }
48	main { max-width:1040px; margin:0 auto; padding:20px; }
49	h1 { font-size:24px; margin:8px 0 16px; }
50	.grid { display:grid; grid-template-columns:repeat(auto-fill, minmax(220px, 1fr)); gap:14px; }
51	.card {
52	  background:#fff; border:1px solid var(--line); border-radius:10px; padding:14px;
53	  position:relative; display:flex; flex-direction:column; gap:8px;
54	}
55	.card h3 { font-size:16px; margin:0; }
56	.card .row { display:flex; justify-content:space-between; align-items:center; gap:8px; }
57	.price { font-weight:700; }
58	.note { font-size:13px; color:var(--warn); }
59	.badge {
60	  display:inline-block; background:#fff3c4; border-radius:6px; padding:1px 6px;
61	  font-size:12px; font-weight:600;
62	}
63	button, .button {
64	  background:var(--green); color:#fff; border:0; border-radius:8px; padding:8px 14px;
65	  font-size:15px; cursor:pointer; text-decoration:none; display:inline-block;
66	}
67	button[disabled] { background:#9aa7a0; cursor:not-allowed; }
68	button.plain { background:#fff; color:var(--ink); border:1px solid var(--line); padding:4px 10px; }
69	select, input[type=number], input[type=text], input[type=email], input[type=password] {
70	  padding:7px; border:1px solid #b9c4be; border-radius:6px; font-size:15px;
71	}
72	input[type=number] { width:64px; }
73	table {
74	  width:100%; border-collapse:collapse; background:#fff; border:1px solid var(--line);
75	  border-radius:10px;
76	}
77	th, td { text-align:left; padding:10px; border-bottom:1px solid var(--line); vertical-align:top; }
78	.totals {
79	  margin-top:16px; background:#fff; border:1px solid var(--line); border-radius:10px;
80	  padding:14px; max-width:380px; margin-left:auto;
81	}
82	.totals div { display:flex; justify-content:space-between; padding:3px 0; }
83	.totals .grand {
84	  font-weight:700; font-size:18px; border-top:1px solid var(--line); margin-top:6px;
85	  padding-top:8px;
86	}
87	.panel {
88	  background:#fff; border:1px solid var(--line); border-radius:10px; padding:14px; margin:14px 0;
89	}
90	.toast {
91	  background:#e5f4ec; border:1px solid #9fd2b5; padding:10px 14px; border-radius:8px;
92	  margin-bottom:14px;
93	}
94	.error {
95	  background:#fdecea; border:1px solid #f1b5ad; padding:10px 14px; border-radius:8px;
96	  margin-bottom:14px;
97	}
98	fieldset {
99	  border:1px solid var(--line); border-radius:10px; background:#fff; margin:0 0 14px;
100	  padding:10px 14px;
101	}
102	legend { font-weight:700; padding:0 6px; }
103	.slots { display:grid; grid-template-columns:repeat(auto-fill, minmax(230px, 1fr)); gap:6px 16px; }
104	.slot { display:flex; gap:8px; align-items:center; padding:4px 0; }
105	.slot.unavailable { color:#5b6660; }
106	.suggestions { margin:6px 0 0; padding-left:18px; font-size:14px; }
107	dialog {
108	  border:1px solid var(--line); border-radius:12px; max-width:900px; width:calc(100% - 32px);
109	}
110	`;
111	
112	// The planted visual bug: on narrow screens the price leaves its row and sits on the button.
113	const BUG_CSS = `@media (max-width: 400px) {
114	  .card .price { position:absolute; right:22px; bottom:20px; font-size:20px; background:#fff; }
115	}`;
116	
117	function pageStyles(): string {
118	  if (bugIsOn("price-overlap")) return CSS + BUG_CSS;
119	  return CSS;
120	}
121	
122	function SignedInAs({ shopper }: { shopper: Shopper }) {
123	  const allergens = shopper.allergens;
124	  const allergenNote = allergens.length ? ` (allergens: ${allergens.join(", ")})` : "";
125	  return (
126	    <span class="who">
127	      Signed in as {shopper.name}
128	      {allergenNote}{" "}
129	      <form method="post" action="/signout" style="display:inline">
130	        <button class="plain" type="submit">
131	          Sign out
132	        </button>
133	      </form>
134	    </span>
135	  );
136	}
137	
138	export function Layout(props: {
139	  title: string;
140	  shopper?: Shopper | null;
141	  basketLines?: number;
142	  children: Child;
143	}) {
144	  return (
145	    <html lang="en">
146	      <head>
